country_event = {
	id = leviathans.4
	hide_window = yes
	is_triggered_only = yes

	trigger = {
		from = {
			is_guardian_country = yes
		}
	}

	immediate = {
		fromfromfrom.solar_system = {
			save_event_target_as = leviathan_destroyed_system
		}
		root = {
			save_event_target_as = leviathan_destroyer_country
		}
		from = {
			save_event_target_as = leviathan_destroyed_country
		}
		country_event = { id = leviathans.6 days = 2 }
	}

	after = {
		if = { # We need an exception for the Enigmatic Fortress since it isnt 'destroyed' the first time around
			limit = {
				OR = {
					from = {
						NOT = {
							has_modifier = enigmatic_power
						}
					}
					AND = {
						root = {
							has_country_flag = enigmatic_fortress_disabled
						}
						from = {
							has_modifier = enigmatic_power
						}
					}
				}
			}
			country_event = { id = timeline.54 } # Timeline Destroyed Leviathan
		}
	}

}

