	id = leviathans.10
	hide_window = yes
	is_triggered_only = yes

	immediate = {
		every_country = {
			limit = { is_country_type = enclave }
			country_event = { id = leviathans.11 }
		}
	}
}

country_event = {
	id = leviathans.11
	hide_window = yes
	is_triggered_only = yes

	immediate = {
		every_controlled_fleet = {
			limit = {
				exists = solar_system
				solar_system = {
					OR = {
						AND = {
							exists = space_owner
							space_owner = {
								is_country_type = default
							}
						}
						AND = {
							any_starbase_in_system = {
								exists = owner
								is_waystation_starbase = yes
								owner = {
									is_country_type = default
								}
							}
						}
					}
				}
			}
			solar_system = {
				if = {
					limit = {
						exists = space_owner
					}
					space_owner = {
						root = {
							add_trust = {
								who = prev
								amount = 1
							}
						}
					}
					random_starbase_in_system = {
						limit = {
							is_waystation_starbase = yes
						}
						owner = {
							root = {
								add_trust = {
									who = prev
									amount = 1
								}
							}
						}
					}
				}
				else = {
					random_starbase_in_system = {
						limit = {
							is_waystation_starbase = yes
						}
						owner = {
							root = {
								add_trust = {
									who = prev
									amount = 1
								}
							}
						}
					}
				}
			}
		}
	}
}

