			text = "leviathans.321.desc"
			success_text = {
				text = "leviathans.321.desc.a"
				check_variable = {
					which = artist_newsletter
					value = 1
				}
			}
			success_text = {
				text = "leviathans.321.desc.b"
				check_variable = {
					which = artist_newsletter
					value = 2
				}
			}
			success_text = {
				text = "leviathans.321.desc.c"
				check_variable = {
					which = artist_newsletter
					value = 3
				}
			}
			success_text = {
				text = "leviathans.321.desc.d"
				check_variable = {
					which = artist_newsletter
					value = 4
				}
			}
		}
	}

	trigger = {
		exists = event_target:artist_enclave_country
		has_modifier = enclave_artist_patron
		NOT = { has_country_flag = enclave_artist_ignores }
	}

	immediate = {
		if = {
			limit = {
				check_variable = {
					which = artist_newsletter
					value < 1
				}
			}
			set_variable = {
				which = artist_newsletter
				value = 1
			}
		}
		else = {
			change_variable = {
				which = artist_newsletter
				value = 1
			}
		}
	}

	# Donate
	option = {
		name = leviathans.321.a
		add_resource = {
			energy = -500
			influence = 50
		}
		allow = {
			resource_stockpile_compare = { resource = energy value >= 500 }
			nomad_can_afford_enclave_cost = { COST = 500 }
		}
		hidden_effect = {
			country_event = { id = leviathans.304 }
		}
	}
	# Cannot afford to donate
	option = {
		name = leviathans.321.c
		hidden_effect = {
			country_event = { id = leviathans.325 }
		}
	}
	# Unsubscribe
	option = {
		name = leviathans.321.b
		default_hide_option = yes
		hidden_effect = {
			set_variable = {
				which = artist_newsletter
				value = 5
			}
			hidden_effect = {
				country_event = { id = leviathans.325 }
			}
		}
	}

	after = {
		hidden_effect = {
			country_event = { id = leviathans.311 days = 240 random = 90 }
		}
	}
}

