country_event = {
	id = leviathans.507
	base = leviathans.500
	desc_clear = yes
	option_clear = yes
	event_message_type = ENCLAVE_DIPLOMACY

	title = leviathans.507.name
	desc = leviathans.507.desc

	immediate = {
		# Set costs based on empire size
		# Base of 500 Energy
        set_variable = {
			which = curator_insight_cost
			value = 500
		}
        # +1% per Empire Size (same scaling as Edicts)
        # Ergo, 1000 Energy at 100 Empire Size
        multiply_variable = {
            which = curator_insight_cost
            value = value:edict_size_effect
        }
	}

	option = {
		name = leviathans.507.a
		allow = {
			NOT = { has_modifier = curator_insight }
			resource_stockpile_compare = {
				resource = energy
				value >= value:curator_purchase_cost|COST|curator_insight_cost|
			}
			nomad_can_afford_enclave_cost = { COST = 100 }
		}

		add_resource = {
			energy = -1
			mult = value:curator_purchase_cost|COST|curator_insight_cost|
		}

		add_modifier = {
			modifier = curator_insight
			days = 3600
		}
		custom_tooltip = opinion20
		hidden_effect = {
			set_country_flag = curator_insight_obtained
			country_event = { id = leviathans.504 } # Post-sale Thanks
			country_event = { id = leviathans.509 days = 3600 } # Renew
			event_target:curator_enclave_country = {
				add_trust = {
					who = root
					amount = 20
				}
			}
		}
	}
	# Back to main menu
	option = {
		name = leviathans.506.d
		hidden_effect = {
			country_event = { id = leviathans.500 }
		}
	}
	#Goodbye
	option = {
		name = GOODBYE
		default_hide_option = yes
	}
	# Fear of the Dark fallback in case you have an ongoing deal.
	option = {
		exclusive_trigger = {
			has_civic = civic_fanatic_purifiers
		}
		name = SCUM
	}
}

