script:
country_event = {
	id = leviathans.4115
	base = leviathans.500
	desc_clear = yes
	option_clear = yes

	desc = leviathans.4115.desc
	desc = {
		trigger = {
			if = {
				limit = {
					event_target:curator_enclave_country = {
						has_country_flag = gave_relic_r_the_modularium
						has_country_flag = gave_relic_r_everchanging_stone
						has_country_flag = gave_relic_r_flowmetal_alloy
						has_country_flag = gave_relic_r_pulsestone
						has_country_flag = gave_relic_r_crystallinus_diffuser
					}
				}
				text = grand_archive.4105.desc.3.no_relic.xeno_geology
			}
			else = {
				text = leviathans.4115.desc
			}
		}
	}

	immediate = {
		if = {
			limit = { NOT = { has_country_flag = rolled_relics_for_xeno_geology } }
			set_country_flag = rolled_relics_for_xeno_geology
			roll_selected_xeno_geology_relic = yes
			roll_selected_xeno_geology_relic = yes
		}
	}

	option = {
	name = grand_archive.4105.3.r_the_modularium
	trigger = {
		is_eligible_for_collection_stage_3_reward_xeno_geology = yes
		has_country_flag = selected_relic_r_the_modularium
		event_target:curator_enclave_country = {
			NOT = { has_country_flag = gave_relic_r_the_modularium }
		}
	}
	allow = {
		has_resource = { type = energy amount >= @curator_stage_3_price }
		custom_tooltip = {
			fail_text = "give_relic_edgecase_tt"
			event_target:curator_enclave_country = {
				NOT = { has_country_flag = gave_relic_$RELIC$ }
			}
		}
	}
	add_resource = { energy = @curator_stage_3_price mult = -1 }
	add_relic = {
		key = r_the_modularium
		full_description = yes
	}
	hidden_effect = {
		event_target:curator_enclave_country = {
			set_country_flag = gave_relic_r_the_modularium
		}
		set_country_flag = received_collection_stage_3_reward_xeno_geology
		# Cleanup
		remove_country_flag = selected_relic_r_the_modularium
		if = {
			limit = { has_country_flag = selected_relic_r_everchanging_stone }
			remove_country_flag = selected_relic_r_everchanging_stone
		}
		else_if = {
			limit = { has_country_flag = selected_relic_r_flowmetal_alloy }
			remove_country_flag = selected_relic_r_flowmetal_alloy
		}
		else_if = {
			limit = { has_country_flag = selected_relic_r_pulsestone }
			remove_country_flag = selected_relic_r_pulsestone
		}
		else_if = {
			limit = { has_country_flag = selected_relic_r_crystallinus_diffuser }
			remove_country_flag = selected_relic_r_crystallinus_diffuser
		}
	}
}


